      "required": [
        "filesScanned",
        "filesSkipped",
        "gaps",
        "scanDirectories"
      ],
      "additionalProperties": false,
      "description": "What the latest check covered."
    },
    "AppSecurityCheck": {
      "type": "object",
      "properties": {
        "id": {
          "type": "string",
          "description": "The check ID, such as CREDENTIAL_LOG_LEAKAGE."
        },
        "title": {
          "type": "string"
        },
        "severity": {
          "type": "string",
          "enum": [
            "high",
            "medium",
            "low"
          ]
        },
        "description": {
          "type": "string"
        },
        "guide": {
          "anyOf": [
            {
              "type": "string",
              "minLength": 1
            },
            {
              "type": "null"
            }
          ],
          "description": "A guide to the check, or null when none is recorded."
        },
        "docsUrl": {
          "anyOf": [
            {
              "type": "string",
              "format": "uri"
            },
            {
              "type": "null"
