app:import:channel-config.description:
Imports the Shopify-authored channel spec for your app as a `channel_config` extension.

  The generated TOML only includes public `channel_config` fields. Review it, then deploy it with `shopify app deploy`.

Use `--json-schema` to print the result, error, and event schemas.

Output from `--json` conforms to the `ImportChannelConfigResult` schema.

```json
{
  "type": "object",
  "properties": {
    "status": {
      "type": "string",
      "const": "success"
    },
    "handle": {
      "type": "string",
      "minLength": 1
    },
    "filename": {
      "type": "string",
      "minLength": 1
    },
    "path": {
      "type": "string",
      "pattern": "^(?:\\/|[a-zA-Z]:[\\\\/]|\\\\\\\\)",
      "description": "Absolute path of the written TOML file."
    },
    "toml": {
      "type": "string",
      "description": "Native channel_config TOML content, unchanged from the export."
    },
    "warnings": {
      "type": "array",
      "items": {
        "$ref": "#/definitions/ChannelSpecExportWarning"
      },
      "description": "Warnings returned with the channel spec export."
    }
  },
  "required": [
    "status",
    "handle",
    "filename",
    "path",
    "toml",
    "warnings"
  ],
  "additionalProperties": false,
  "title": "ImportChannelConfigResult",
  "definitions": {
    "ChannelSpecExportWarning": {
      "type": "object",
      "properties": {
        "code": {
          "type": "string"
        },
        "message": {
          "type": "string"
        }
      },
      "required": [
        "code",
        "message"
      ],
      "additionalProperties": false
    }
  },
  "$schema": "http://json-schema.org/draft-07/schema#"
}
```

app:import:custom-data-definitions.description:
Import metafield and metaobject definitions from your development store. "Read more about declarative custom data definitions" (https://shopify.dev/docs/apps/build/custom-data/declarative-custom-data-definitions).

Use `--json-schema` to print the result, error, and event schemas.

Output from `--json` conforms to the `ImportCustomDataDefinitionsResult` schema.

```json
{
  "type": "object",
  "properties": {
    "status": {
      "type": "string",
      "const": "success"
    },
    "storeDomain": {
      "type": [
        "string",
        "null"
      ],
      "description": "The full myshopify.com domain of the development store, or null when unavailable."
    },
    "metafieldCount": {
      "type": "integer",
      "minimum": 0,
      "description": "The number of available metafields converted to TOML."
    },
    "metaobjectCount": {
      "type": "integer",
      "minimum": 0,
      "description": "The number of available metaobjects converted to TOML."
    },
    "toml": {
      "type": "string",
      "description": "Suggested native TOML for app-reserved definitions. No file is written."
    },
    "skippedSections": {
      "type": "array",
      "items": {
        "anyOf": [
          {
            "$ref": "#/definitions/SkippedMetafields"
          },
          {
            "$ref": "#/definitions/SkippedMetaobjects"
          }
        ]
      },
      "description": "Sections skipped because required access scopes are unavailable. An empty array means all requests were authorized."
    }
  },
  "required": [
    "status",
    "storeDomain",
    "metafieldCount",
    "metaobjectCount",
    "toml",
    "skippedSections"
  ],
  "additionalProperties": false,
  "title": "ImportCustomDataDefinitionsResult",
  "definitions": {
    "SkippedMetafields": {
      "type": "object",
      "properties": {
        "type": {
          "type": "string",
          "const": "metafields"
        },
        "ownerType": {
          "type": "string",
          "minLength": 1,
          "description": "The Admin API metafield owner type, such as PRODUCT."
        }
      },
      "required": [
        "type",
        "ownerType"
      ],
      "additionalProperties": false
    },
    "SkippedMetaobjects": {
      "type": "object",
      "properties": {
        "type": {
          "type": "string",
          "const": "metaobjects"
        }
      },
      "required": [
        "type"
      ],
      "additionalProperties": false
    }
  },
  "$schema": "http://json-schema.org/draft-07/schema#"
}
```

app:import:dashboard-extensions.description:
Import dashboard-managed extensions into your app.

Use `--json-schema` to print the result, error, and event schemas.

Output from `--json` conforms to the `ImportDashboardExtensionsResult` schema.

```json
{
  "type": "object",
  "properties": {
    "status": {
      "type": "string",
      "enum": [
        "success",
        "partial",
        "skipped",
        "cancelled"
      ]
    },
    "reason": {
      "anyOf": [
        {
          "type": "string",
          "enum": [
            "no-extensions",
            "directory-selection-cancelled"
          ]
        },
        {
          "type": "null"
        }
      ]
    },
    "extensions": {
      "type": "array",
      "items": {
        "$ref": "#/definitions/ImportedDashboardExtension"
      },
      "description": "Completed extension imports and kept local directories, in selection order."
    },
    "errors": {
      "type": "array",
      "items": {
        "$ref": "#/definitions/ExtensionImportFailure"
      },
      "description": "Failed selected imports or identifier persistence."
    },
    "identifiersUpdated": {
      "type": "boolean",
      "description": "Whether the extension identifier persistence step completed."
    }
  },
  "required": [
    "status",
    "reason",
    "extensions",
    "errors",
    "identifiersUpdated"
  ],
  "additionalProperties": false,
  "title": "ImportDashboardExtensionsResult",
  "definitions": {
    "ImportedDashboardExtension": {
      "type": "object",
      "properties": {
        "id": {
          "type": "string",
          "format": "uuid",
          "description": "The dashboard extension registration UUID, not a Shopify GID."
        },
        "name": {
          "type": "string"
        },
        "type": {
          "type": "string",
          "minLength": 1,
          "description": "The upstream dashboard extension type."
        },
        "directory": {
          "type": "string",
          "description": "The absolute local extension directory."
        },
        "configurationPath": {
          "anyOf": [
            {
              "$ref": "#/definitions/ImportedDashboardExtension/properties/directory"
            },
            {
              "type": "null"
            }
          ],
          "description": "The absolute local TOML path, or null when no TOML file exists in a kept directory."
        },
        "changed": {
          "type": "boolean",
          "description": "Whether this import wrote the local extension TOML."
        }
      },
      "required": [
        "id",
        "name",
        "type",
        "directory",
        "configurationPath",
        "changed"
      ],
      "additionalProperties": false
    },
    "ExtensionImportFailure": {
      "type": "object",
      "properties": {
        "extensionId": {
          "anyOf": [
            {
              "type": "string",
              "format": "uuid"
            },
            {
              "type": "null"
            }
          ],
          "description": "The registration UUID, or null for identifier persistence."
        },
        "error": {
          "$ref": "#/definitions/JsonError"
        }
      },
      "required": [
        "extensionId",
        "error"
      ],
      "additionalProperties": false
    },
    "JsonError": {
      "anyOf": [
        {
          "$ref": "#/definitions/JsonAbortError"
        },
        {
          "$ref": "#/definitions/JsonBugError"
        },
        {
          "$ref": "#/definitions/JsonExternalError"
        }
      ]
    },
    "JsonErrorCustomSection": {
      "type": "object",
      "properties": {
        "title": {
          "type": "string"
        },
        "body": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "array",
              "items": {
                "type": "array",
                "items": {
                  "type": "string"
                }
              }
            }
          ]
        }
      },
      "required": [
        "body"
      ],
      "additionalProperties": false
    },
    "JsonAbortError": {
      "type": "object",
      "properties": {
        "type": {
          "type": "string",
          "const": "abort"
        },
        "message": {
          "type": "string"
        },
        "code": {
          "type": "string",
          "minLength": 1,
          "description": "A stable error code, included only when known."
        },
        "tryMessage": {
          "type": "string"
        },
        "nextSteps": {
          "type": "array",
          "items": {
            "type": "string"
          }
        },
        "customSections": {
          "type": "array",
          "items": {
            "$ref": "#/definitions/JsonErrorCustomSection"
          }
        },
        "details": {
          "description": "Selected domain details, preserving native API payloads such as GraphQL errors, extensions, and data."
        }
      },
      "required": [
        "type",
        "message"
      ],
      "additionalProperties": false
    },
    "JsonBugError": {
      "type": "object",
      "properties": {
        "type": {
          "type": "string",
          "const": "bug"
        },
        "message": {
          "$ref": "#/definitions/JsonAbortError/properties/message"
        },
        "code": {
          "$ref": "#/definitions/JsonAbortError/properties/code"
