theme:init.description:
Clones a Git repository to your local machine to use as the starting point for building a theme.

  If no Git repository is specified, then this command creates a copy of Shopify's "Skeleton theme" (https://github.com/Shopify/skeleton-theme.git), with the specified name in the current folder. If no name is provided, then you're prompted to enter one.

  > Caution: If you're building a theme for the Shopify Theme Store, then you can use our example theme as a starting point. However, the theme that you submit needs to be "substantively different from existing themes" (https://shopify.dev/docs/themes/store/requirements#uniqueness) so that it provides added value for users.


Use `--json-schema` to print the result, error, and event schemas.

Output from `--json` conforms to the `ThemeInitResult` schema.

```json
{
  "type": "object",
  "properties": {
    "status": {
      "type": "string",
      "enum": [
        "success",
        "partial"
      ]
    },
    "changed": {
      "type": "boolean",
      "const": true
    },
    "directory": {
      "$ref": "#/definitions/AbsolutePath"
    },
    "repoUrl": {
      "type": "string",
      "minLength": 1,
      "description": "The source Git remote (including HTTPS, SSH, or SCP-style Git URLs)."
    },
    "latest": {
      "type": "boolean"
    },
    "aiInstructions": {
      "anyOf": [
        {
          "type": "string",
          "enum": [
            "all",
            "github",
            "cursor",
            "claude"
          ]
        },
        {
          "type": "null"
        }
      ]
    },
    "instructionFilePaths": {
      "anyOf": [
        {
          "type": "array",
          "items": {
            "$ref": "#/definitions/AbsolutePath"
          }
        },
        {
          "type": "null"
        }
      ],
      "description": "Created instruction files, or null when setup failed before their completion could be established."
    },
    "reason": {
      "type": [
        "string",
        "null"
      ],
      "description": "The reason for incomplete setup, or null when setup completed."
    }
  },
  "required": [
    "status",
    "changed",
    "directory",
    "repoUrl",
    "latest",
    "aiInstructions",
    "instructionFilePaths",
    "reason"
  ],
  "additionalProperties": false,
  "title": "ThemeInitResult",
  "definitions": {
    "AbsolutePath": {
      "type": "string",
      "description": "An absolute native filesystem path."
    }
  },
  "$schema": "http://json-schema.org/draft-07/schema#"
}
```

