doc:fetch.description:
Download a complete document from shopify.dev. Every page on shopify.dev has a Markdown version, and that is what this tool returns. Use this to pull an entire document verbatim — for example, a set of instructions an agent follows like a centrally-served skill. Pass `--language` for the language of the app you are building so code examples match your stack. For finding the relevant pieces of content across shopify.dev instead, use `doc search`.

Use `--json-schema` to print the result, error, and event schemas.

Output from `--json` conforms to the `DocFetchResult` schema.

```json
{
  "anyOf": [
    {
      "type": "object",
      "properties": {
        "document": {
          "$ref": "#/definitions/Document"
        }
      },
      "required": [
        "document"
      ],
      "additionalProperties": false
    },
    {
      "$ref": "#/definitions/DocumentFile"
    }
  ],
  "title": "DocFetchResult",
  "definitions": {
    "Document": {
      "type": "object",
      "properties": {
        "url": {
          "type": "string",
          "format": "uri",
          "description": "The requested shopify.dev document URL."
        },
        "content": {
          "type": "string",
          "description": "The document in Markdown, with the requested language filter applied."
        }
      },
      "required": [
        "url",
        "content"
      ],
      "additionalProperties": false
    },
    "DocumentFile": {
      "type": "object",
      "properties": {
        "path": {
          "type": "string",
          "pattern": "^(?:\\/|[A-Za-z]:[\\\\/]|\\\\\\\\)",
          "description": "The absolute native path of the written file."
        },
        "format": {
          "type": "string",
          "const": "markdown",
          "description": "The file contains the original Markdown document, not a JSON wrapper."
        }
      },
      "required": [
        "path",
        "format"
      ],
      "additionalProperties": false
    }
  },
  "$schema": "http://json-schema.org/draft-07/schema#"
}
```

doc:search.description:
Query the shopify.dev vector store and print the most relevant documentation chunks as JSON. Best for programmatic discovery — surfacing the relevant pieces of documentation for a topic, rather than retrieving a whole document. To download a full document verbatim, use `doc fetch`.

Use `--json-schema` to print the result, error, and event schemas.

Output from `--json` conforms to the `DocSearchResult` schema.

```json
{
  "type": "object",
  "properties": {
    "results": {
      "type": "array",
      "items": {
        "$ref": "#/definitions/DocumentationSearchEntry"
      },
      "description": "The top matching chunks from one search request."
    },
    "pageInfo": {
      "$ref": "#/definitions/PageInfo"
    }
  },
  "required": [
    "results",
    "pageInfo"
  ],
  "additionalProperties": false,
  "title": "DocSearchResult",
  "definitions": {
    "DocumentationSearchEntry": {
      "type": "object",
      "properties": {
        "score": {
          "type": "number",
          "description": "The relevance score returned by shopify.dev."
        },
        "content": {
          "type": "string",
          "description": "The matching documentation chunk."
        },
        "url": {
          "type": "string",
          "format": "uri",
          "description": "The URL of the matching document."
        },
        "title": {
          "type": "string",
          "description": "The title of the matching document."
        },
        "domain": {
          "type": [
            "string",
            "null"
          ],
          "description": "The documentation domain, or null when unavailable."
        }
      },
      "required": [
        "score",
        "content",
        "url",
        "title",
        "domain"
      ],
      "additionalProperties": false
    },
    "PageInfo": {
      "type": "object",
      "properties": {
        "hasNextPage": {
          "type": [
            "boolean",
            "null"
          ],
          "description": "Whether more results are available, or null when unknown."
        }
      },
      "required": [
        "hasNextPage"
      ],
      "additionalProperties": false
    }
  },
  "$schema": "http://json-schema.org/draft-07/schema#"
}
```

config:autoupgrade:off.description:
Disable automatic upgrades for Shopify CLI.

  When auto-upgrade is disabled, Shopify CLI won't automatically update. Run `shopify upgrade` to update manually.

  To enable auto-upgrade, run `shopify config autoupgrade on`.


Use `--json-schema` to print the result, error, and event schemas.

Output from `--json` conforms to the `AutoUpgradeResult` schema.

